CREATE TABLE coupon_claim (id BIGINT NOT NULL AUTO_INCREMENT,coupon_id BIGINT NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'claimed',idempotency_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,claimed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),redeemed_order_id BIGINT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_coupon_claim_idempotency UNIQUE(user_id,idempotency_key),KEY idx_coupon_claim_user(user_id,status,claimed_at DESC,id DESC),KEY idx_coupon_claim_coupon(coupon_id,user_id,status),KEY idx_coupon_claim_redeemed_order(redeemed_order_id),CONSTRAINT ck_coupon_claim_status CHECK(status IN ('claimed','redeemed','expired')),CONSTRAINT ck_coupon_claim_redemption CHECK((status='redeemed' AND redeemed_order_id IS NOT NULL) OR (status IN ('claimed','expired') AND redeemed_order_id IS NULL)),CONSTRAINT ck_coupon_claim_idempotency CHECK(REGEXP_LIKE(idempotency_key,'^[A-Za-z0-9._:-]{8,128}$','c')),CONSTRAINT fk_coupon_claim_coupon FOREIGN KEY(coupon_id) REFERENCES coupon_definition(id) ON DELETE RESTRICT,CONSTRAINT fk_coupon_claim_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
